package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// --- record definitions ---

type SalesRec struct {
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

// TierTable as per COBOL OCCURS 4
type TierEntry struct {
	TierLimit decimal.Decimal // PIC 9(6)V99
	TierRate  decimal.Decimal // PIC 9V99
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var tierEntries [4]TierEntry

var salesFile *os.File
var scanner *bufio.Scanner
var curSalesRec SalesRec
var inputDone bool

func isInputDone() bool { return WsEofFlag == "Y" }
func setInputDone() { WsEofFlag = "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// storeDecimal implements COBOL high-order truncation for numeric fields
// intDigits = number of 9's before V, scale = digits after V
func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// bring to target scale first (caller should have rounded/truncated)
	// then drop high-order integer digits if overflow
	// modulus = 10^(intDigits+scale) on scaled integer
	pow10 := decimal.New(1, int32(intDigits+int(scale))) // 10^(intDigits+scale)
	scaled := v.Shift(scale)                              // v *10^scale
	// Use Mod to keep low-order digits; handle negative
	// decimal.Mod does: a - b*Floor(a/b) for positive, sign follows dividend
	// For our range values are non-negative, simple.
	rem := scaled.Mod(pow10)
	// shopspring Mod for negative returns negative remainder, which matches COBOL sign preservation
	return rem.Shift(-scale)
}

// storeInt truncates to digits decimal digits (high-order drop)
func storeInt(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// preserve sign for completeness
	if v < 0 {
		return -((-v) % mod)
	}
	return v % mod
}

// numeric-edited formatting
func formatEdited(v decimal.Decimal, picture string) string {
	// count decimal places after '.'
	dotIdx := strings.Index(picture, ".")
	decPlaces := 0
	if dotIdx >= 0 {
		for i := dotIdx + 1; i < len(picture); i++ {
			c := picture[i]
			if c == 'Z' || c == '9' {
				decPlaces++
			}
		}
	}
	// integer digit slots before dot
	intSlots := 0
	intStart := 0
	intEnd := len(picture)
	if dotIdx >= 0 {
		intEnd = dotIdx
	}
	for i := intStart; i < intEnd; i++ {
		if picture[i] == 'Z' || picture[i] == '9' {
			intSlots++
		}
	}
	// prepare integer and fractional strings
	negative := v.Sign() < 0
	av := v.Abs()
	// Ensure scale = decPlaces (value already has it)
	// Get integer part and fractional part as strings
	// Use string representation with exactly decPlaces
	// format with Shift
	scaled := av.Shift(int32(decPlaces)) // av*10^decPlaces
	// scaled should be integer (no fractional)
	// Get integer representation
	// Use Truncate to avoid floating
	scaledInt := scaled.Truncate(0)
	// Convert to string without sign
	s := scaledInt.String() // decimal integer string (no exponent ideally)
	// Remove minus if any (av is abs)
	// Ensure s has at least decPlaces+1 digits (pad leading zeros)
	if len(s) <= decPlaces {
		s = strings.Repeat("0", decPlaces+1-len(s)) + s
	}
	var intPartStr string
	var fracPartStr string
	if decPlaces > 0 {
		intPartStr = s[:len(s)-decPlaces]
		fracPartStr = s[len(s)-decPlaces:]
	} else {
		intPartStr = s
		fracPartStr = ""
	}
	// Handle high-order truncation: keep low-order intSlots digits
	if len(intPartStr) > intSlots {
		intPartStr = intPartStr[len(intPartStr)-intSlots:]
	}
	// Now fill digits into picture
	// Build result array
	res := make([]byte, len(picture))
	for i := 0; i < len(picture); i++ {
		res[i] = picture[i]
	}
	// Fill fractional digits (right side)
	fracIdx := 0
	if dotIdx >= 0 {
		for i := dotIdx + 1; i < len(picture); i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				if fracIdx < len(fracPartStr) {
					res[i] = fracPartStr[fracIdx]
					fracIdx++
				} else {
					res[i] = '0'
				}
			} else {
				// literal '.' already
			}
		}
	}
	// Fill integer digits from rightmost integer placeholder to left
	// Collect integer placeholder indices
	var intPlaceIdx []int
	for i := intStart; i < intEnd; i++ {
		if picture[i] == 'Z' || picture[i] == '9' {
			intPlaceIdx = append(intPlaceIdx, i)
		}
	}
	// intPartStr digits left-padded to intSlots
	paddedInt := intPartStr
	if len(paddedInt) < len(intPlaceIdx) {
		paddedInt = strings.Repeat("0", len(intPlaceIdx)-len(paddedInt)) + paddedInt
	}
	// Map rightmost
	for k := len(intPlaceIdx) - 1; k >= 0; k-- {
		pos := intPlaceIdx[k]
		// digit char from paddedInt (rightmost corresponds)
		// paddedInt length == len(intPlaceIdx)
		digit := paddedInt[k]
		res[pos] = digit
	}

	// Apply Z suppression on integer part
	// Iterate integer placeholders left to right
	suppressing := true
	for idx, pos := range intPlaceIdx {
		picChar := picture[pos]
		if picChar == 'Z' && suppressing {
			if res[pos] == '0' {
				// Check if this is the last integer placeholder and it's the only '9' logic?
				// For Z, space
				res[pos] = ' '
			} else {
				suppressing = false
			}
		} else {
			// '9' or Z after suppression ends
			suppressing = false
			// keep digit as is
		}
		_ = idx
	}
	// Commas inside suppressed zone become spaces
	for i := 0; i < len(picture); i++ {
		if picture[i] == ',' {
			// check if all integer placeholders strictly to the left are spaces
			hasSignificantLeft := false
			for _, p := range intPlaceIdx {
				if p < i {
					if res[p] != ' ' {
						hasSignificantLeft = true
						break
					}
				}
			}
			if !hasSignificantLeft {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		}
	}
	// Handle sign: not needed for this program (all positive). If negative,
	// COBOL would put '-'? For unsigned pics sign is ignored. We ignore.
	if negative {
		// For completeness, put '-' at leftmost? Not required.
	}
	return string(res)
}

func formatUneditedInt(v int64, digits int) string {
	// zero-padded to digits width, high-order truncation already applied
	// handle negative with sign? Not needed
	sig := ""
	neg := v < 0
	if neg {
		v = -v
	}
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	sig = fmt.Sprintf("%0*d", digits, func() int {
		// produce int value from s? s already truncated
		// just pad
		return 0
	})
	// Simpler: pad s with leading zeros to digits
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	_ = sig
	if neg {
		// COBOL would show sign? unsigned would still maybe? ignore
	}
	return s
}

// Helpers for DISPLAY of numeric unedited: PIC 9 and PIC 9(3)
func displayUneditedInt(v int64, width int) string {
	v = storeInt(v, width)
	// zero padded
	s := fmt.Sprintf("%d", v)
	if v < 0 {
		// handle negative: COBOL would display sign? Keep as decimal
		// For width includes sign? Not needed
		abs := -v
		s = fmt.Sprintf("%d", abs)
		if len(s) > width-1 {
			s = s[len(s)-(width-1):]
		}
		s = "-" + strings.Repeat("0", width-1-len(s)) + s
		return s
	}
	if len(s) > width {
		s = s[len(s)-width:]
	}
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func parseSalesRec(line string) SalesRec {
	// line already padded to 12
	var r SalesRec
	if len(line) < 12 {
		line = padRight(line, 12)
	}
	r.SrId = line[0:4]
	field := line[4:12] // 8 chars digits
	// digits only; may contain spaces? Treat spaces as zeros? Assume digits
	trimmed := strings.TrimSpace(field)
	if trimmed == "" {
		trimmed = "0"
	}
	// Remove any non-digit (should be digits)
	// Parse as integer
	// field may have spaces padding; after padRight spaces remain
	// So we take 0-8 and if contains spaces replace with 0? But spec says numeric DISPLAY digits only
	// Use trimmed numeric
	// Actually if line shorter, pad spaces, field may be spaces -> 0
	clean := ""
	for _, ch := range field {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		clean = "0"
	}
	// clean length should be <=8
	n, _ := decimal.NewFromString(clean)
	// PIC 9(6)V99 => value = digits *10^{-2}
	r.SrSales = decimal.NewFromBigInt(n.BigInt(), -2)
	return r
}

// Paragraphs

func InitPara() {
	tierEntries[0].TierLimit = decimal.NewFromInt(1000).Truncate(2) // 1000.00
	// Use decimal for exact
	tierEntries[0].TierLimit = decimal.RequireFromString("1000.00")
	tierEntries[0].TierRate = storeDecimal(decimal.RequireFromString("2.50"), 1, 2)
	tierEntries[1].TierLimit = decimal.RequireFromString("5000.00")
	tierEntries[1].TierRate = storeDecimal(decimal.RequireFromString("4.00"), 1, 2)
	tierEntries[2].TierLimit = decimal.RequireFromString("20000.00")
	tierEntries[2].TierRate = storeDecimal(decimal.RequireFromString("5.50"), 1, 2)
	tierEntries[3].TierLimit = decimal.RequireFromString("999999.99")
	tierEntries[3].TierRate = storeDecimal(decimal.RequireFromString("7.25"), 1, 2)
}

func ReadPara() {
	if scanner == nil {
		setInputDone()
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		line = padRight(line, 12)
		curSalesRec = parseSalesRec(line)
		WsEofFlag = "N"
		inputDone = false
	} else {
		setInputDone()
		inputDone = true
	}
}

func ProcessPara() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if curSalesRec.SrSales.Cmp(tierEntries[WsIdx-1].TierLimit) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	rate := tierEntries[WsTier-1].TierRate
	raw := curSalesRec.SrSales.Mul(rate).Shift(-2) // /100
	rounded := raw.Round(2)
	WsComm = storeDecimal(rounded, 6, 2)

	WsTotal = WsTotal.Add(WsComm)
	WsTotal = storeDecimal(WsTotal, 9, 2)

	WsCount = storeInt(WsCount+1, 3)

	// MOVE to edited
	WsSalesEd = formatEdited(curSalesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	tierStr := displayUneditedInt(WsTier, 1)
	// SR-ID as is (4 chars)
	fmt.Printf("%s T%s %s %s%% %s\n", curSalesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := displayUneditedInt(WsCount, 3)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	InitPara()
	f, err := os.Open("input.dat")
	if err != nil {
		// If file missing, treat as empty (still summary)
		// Create empty scanner that immediately hits EOF
		WsEofFlag = "N"
		// open will fail; we still need to do process loop with empty file
		// Simulate empty
		scanner = bufio.NewScanner(strings.NewReader(""))
		// But also need to handle close not needed
	} else {
		salesFile = f
		scanner = bufio.NewScanner(f)
		defer f.Close()
	}
	// If file not opened, scanner already set
	if scanner == nil {
		scanner = bufio.NewScanner(strings.NewReader(""))
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if salesFile != nil {
		salesFile.Close()
	}
	SummaryPara()
}
